(function(){'use strict';function close(c,focus){if(!c.classList.contains('is-open'))return;c.classList.remove('is-open');var t=c.querySelector('.custom-select-trigger');t.setAttribute('aria-expanded','false');if(focus)t.focus()}function open(c){document.querySelectorAll('.custom-select.is-open').forEach(function(x){if(x!==c)close(x,false)});c.classList.add('is-open');c.querySelector('.custom-select-trigger').setAttribute('aria-expanded','true')}function sync(c){var s=c.querySelector('select'),t=c.querySelector('.custom-select-trigger'),o=[].slice.call(c.querySelectorAll('.custom-select-option'));t.querySelector('.custom-select-label').textContent=s.options[s.selectedIndex].text;t.setAttribute('aria-label',(s.getAttribute('aria-label')||'选择')+'：'+s.options[s.selectedIndex].text);o.forEach(function(x,i){x.setAttribute('aria-selected',String(i===s.selectedIndex))})}function enhance(s){var c=s.parentElement;if(!c||c.dataset.enhanced)return;c.dataset.enhanced='true';c.classList.add('custom-select');s.tabIndex=-1;s.setAttribute('aria-hidden','true');var t=document.createElement('button');t.type='button';t.className='custom-select-trigger';t.setAttribute('aria-haspopup','listbox');t.setAttribute('aria-expanded','false');t.innerHTML='<span class="custom-select-label"></span><svg class="custom-select-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 9l7 7 7-7" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';var m=document.createElement('div');m.className='custom-select-menu';m.setAttribute('role','listbox');[].slice.call(s.options).forEach(function(x,i){var o=document.createElement('button');o.type='button';o.tabIndex=-1;o.className='custom-select-option';o.setAttribute('role','option');o.textContent=x.text;o.addEventListener('click',function(){s.selectedIndex=i;s.dispatchEvent(new Event('change',{bubbles:true}));sync(c);close(c,true)});m.appendChild(o)});c.appendChild(t);c.appendChild(m);sync(c);t.addEventListener('click',function(){c.classList.contains('is-open')?close(c,false):open(c)});t.addEventListener('keydown',function(e){var n=s.options.length,i=s.selectedIndex;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();open(c);s.selectedIndex=e.key==='ArrowDown'?Math.min(i+1,n-1):Math.max(i-1,0);s.dispatchEvent(new Event('change',{bubbles:true}));sync(c)}else if(e.key==='Home'||e.key==='End'){e.preventDefault();s.selectedIndex=e.key==='Home'?0:n-1;s.dispatchEvent(new Event('change',{bubbles:true}));sync(c);open(c)}else if(e.key==='Enter'||e.key===' '){e.preventDefault();c.classList.contains('is-open')?close(c,false):open(c)}else if(e.key==='Escape'){e.preventDefault();close(c,true)}});s.addEventListener('change',function(){sync(c)});c.addEventListener('focusout',function(e){if(!e.relatedTarget||!c.contains(e.relatedTarget))close(c,false)})}document.addEventListener('click',function(e){document.querySelectorAll('.custom-select.is-open').forEach(function(c){if(!c.contains(e.target))close(c,false)})});document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.custom-select>select').forEach(enhance)})}());
